.trx_demo_tabs_style_icons [class*="hint_"]:before {
	position: absolute;
	-webkit-transform: translateZ(0);
	transform: translateZ(0);
	visibility: hidden;
	opacity: 0;
	z-index: 1000000;
	pointer-events: none;
	-webkit-transition: .3s ease;
	transition: .3s ease;
	-webkit-transition-delay: 0ms;
	transition-delay: 0ms;
